function timeFunc($function, $runs)
{
  $times = array();

  for ($i = 0; $i < $runs; $i++)
  {
    $time = microtime();
    call_emp_func($function);
    $times[$i] = microtime() - $time;
  }

  return array_sum($times) / $runs;
}

